-- Actual Staging column definitions; local fixtures omit live RLS/triggers.
CREATE TABLE public.job_budget_divisions (id uuid DEFAULT gen_random_uuid() NOT NULL,job_id uuid NOT NULL,name text NOT NULL,code text,sort_order integer DEFAULT 10 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,archived_at timestamp with time zone,archived_by text,archive_reason text);
CREATE TABLE public.job_pay_application_change_orders (id uuid DEFAULT gen_random_uuid() NOT NULL,pay_application_id uuid NOT NULL,change_order_id uuid NOT NULL,co_number text NOT NULL,description text,approved_value numeric(14,2) NOT NULL,previous_billed_amount numeric(14,2) DEFAULT 0 NOT NULL,additional_percent numeric(9,6) DEFAULT 0 NOT NULL,calculated_current_amount numeric(14,2) DEFAULT 0 NOT NULL,final_current_amount numeric(14,2) DEFAULT 0 NOT NULL,override_reason text,overridden_by text,overridden_at timestamp with time zone,billed_to_date_amount numeric(14,2) DEFAULT 0 NOT NULL,remaining_amount numeric(14,2) DEFAULT 0 NOT NULL,source_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.job_pay_application_lines (id uuid DEFAULT gen_random_uuid() NOT NULL,pay_application_id uuid NOT NULL,sov_line_id uuid,source_budget_line_id uuid,project_division_id uuid,project_division_code text,project_division_name text,cost_code text,description text NOT NULL,original_budget_amount numeric(14,2) DEFAULT 0 NOT NULL,source_fee_amount numeric(14,2) DEFAULT 0 NOT NULL,allocated_fee_amount numeric(14,2) DEFAULT 0 NOT NULL,scheduled_value_amount numeric(14,2) DEFAULT 0 NOT NULL,previous_billed_percent numeric(9,6) DEFAULT 0 NOT NULL,additional_percent numeric(9,6) DEFAULT 0 NOT NULL,resulting_percent numeric(9,6) DEFAULT 0 NOT NULL,previous_billed_amount numeric(14,2) DEFAULT 0 NOT NULL,calculated_current_amount numeric(14,2) DEFAULT 0 NOT NULL,final_current_amount numeric(14,2) DEFAULT 0 NOT NULL,override_reason text,overridden_by text,overridden_at timestamp with time zone,billed_to_date_amount numeric(14,2) DEFAULT 0 NOT NULL,remaining_amount numeric(14,2) DEFAULT 0 NOT NULL,snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.job_pay_applications (id uuid DEFAULT gen_random_uuid() NOT NULL,job_id uuid NOT NULL,pay_app_number integer NOT NULL,billing_period_start date,billing_period_end date DEFAULT CURRENT_DATE NOT NULL,status text DEFAULT 'draft'::text NOT NULL,original_contract_value numeric(14,2) DEFAULT 0 NOT NULL,approved_change_order_value numeric(14,2) DEFAULT 0 NOT NULL,current_contract_value numeric(14,2) DEFAULT 0 NOT NULL,original_previous_billed numeric(14,2) DEFAULT 0 NOT NULL,original_current_billed numeric(14,2) DEFAULT 0 NOT NULL,change_order_previous_billed numeric(14,2) DEFAULT 0 NOT NULL,change_order_current_billed numeric(14,2) DEFAULT 0 NOT NULL,total_previous_billed numeric(14,2) DEFAULT 0 NOT NULL,total_current_billed numeric(14,2) DEFAULT 0 NOT NULL,total_billed_to_date numeric(14,2) DEFAULT 0 NOT NULL,remaining_contract_value numeric(14,2) DEFAULT 0 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,created_by text NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,updated_by text,approved_at timestamp with time zone,approved_by text,billed_at timestamp with time zone,billed_by text,finalization_key uuid,pay_app_kind text DEFAULT 'standard'::text NOT NULL,correction_of_id uuid,retainage_percent numeric(7,4) DEFAULT 0 NOT NULL,retainage_amount numeric(14,2) DEFAULT 0 NOT NULL,template_key text DEFAULT 'aia_g702_g703'::text NOT NULL,template_document_id uuid,approval_note text,billed_note text,voided_at timestamp with time zone,voided_by text,void_reason text);
CREATE TABLE public.job_revenue_lines (id uuid DEFAULT gen_random_uuid() NOT NULL,job_id uuid NOT NULL,division text NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,archived_at timestamp with time zone,archived_by text,archive_reason text,sov_line text,description text NOT NULL,scheduled_value_amount numeric DEFAULT 0 NOT NULL,approved_change_amount numeric DEFAULT 0 NOT NULL,billed_to_date_amount numeric DEFAULT 0 NOT NULL,note text,created_by text,is_protected_financial boolean DEFAULT false NOT NULL,source_budget_line_id uuid,source_project_division_id uuid,source_original_budget_amount numeric(14,2),allocation_percent numeric(9,6),allocated_fee_amount numeric(14,2) DEFAULT 0 NOT NULL,billing_locked_at timestamp with time zone);
